terraform {
  required_providers {
    azurerm = { source = "hashicorp/azurerm", version = "~> 3.0" }
  }
  backend "azurerm" {
    resource_group_name  = "rg-terraform-state"
    storage_account_name = "satishtfstate"
    container_name        = "tfstate"
    key                    = "orders-pipeline.tfstate"
    # Azure Blob's native lease mechanism handles locking --
    # no separate DynamoDB-equivalent table needed
  }
}

provider "azurerm" { features {} }

resource "azurerm_resource_group" "pipeline" {
  name     = "rg-orders-pipeline"
  location = "eastus"
}

module "storage" {
  source              = "./modules/storage-account"
  resource_group_name = azurerm_resource_group.pipeline.name
  location             = azurerm_resource_group.pipeline.location
  account_name          = "satishpipeline"
}

